 model=s.model();S=[0]+[1<<i for i in range(m)]+[model.eval(c).as_long() for c in cols];json.dump({'support':S,'weight':w},open('workspace/agent1_pointset_rank_sat.json','w'));print(S)
else:print(s.reason_unknown())

