 for mode in [0,1]:
  p=list(range(m))
  for i in range(k):p[off+i]=off+((i+1)%k if mode==0 else (1-i if i<2 else i))
  gens.append(lambda x,p=p:bitperm(x,p))
for fn in gens:
 for x in range(n):union(x,fn(x))
