  if x&b:vec[x]^=vec[x^b]
rows=[]
for x in range(n):
 d=x.bit_count()
 if d>7:rows.extend([(vec[x],0),(vec[x]<<N,0)])
 elif d==7:rows.append((vec[x]^(vec[x]<<N),int(anfg[x])))
for j,sz in enumerate(sizes):
 if sz>238:rows.extend([(1<<j,0),(1<<(j+N),0)])
B={};R={}
